CREATE OR ALTER PROCEDURE [dbo].[uspFoodSafetyChecklistResult_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ChecklistId UNIQUEIDENTIFIER = NULL
	, @ChecklistItemId UNIQUEIDENTIFIER = NULL
	, @ShiftId UNIQUEIDENTIFIER = NULL
	, @ProductionBatchId UNIQUEIDENTIFIER = NULL
	, @WorkstationId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ChecklistId]
			, t.[ChecklistItemId]
			, t.[CheckDate]
			, t.[ShiftId]
			, j1.[Name] AS [ShiftName]
			, t.[ProductionBatchId]
			, j2.[BatchNo] AS [ProductionBatchName]
			, t.[WorkstationId]
			, t.[ResultCode]
			, t.[ActualValue]
			, t.[CheckedBy]
			, t.[CheckedAt]
			, t.[CorrectiveAction]
			, t.[EvidenceUrl]
			, t.[CreatedDate]
		FROM [dbo].[FoodSafetyChecklistResult] AS t
		LEFT JOIN [dbo].[Shift] AS j1 ON j1.[Id] = t.[ShiftId]
		LEFT JOIN [dbo].[ProductionBatche] AS j2 ON j2.[Id] = t.[ProductionBatchId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ResultCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ChecklistId IS NULL OR t.[ChecklistId] = @ChecklistId)
			AND (@ChecklistItemId IS NULL OR t.[ChecklistItemId] = @ChecklistItemId)
			AND (@ShiftId IS NULL OR t.[ShiftId] = @ShiftId)
			AND (@ProductionBatchId IS NULL OR t.[ProductionBatchId] = @ProductionBatchId)
			AND (@WorkstationId IS NULL OR t.[WorkstationId] = @WorkstationId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'checklistId' THEN r.[ChecklistId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'checklistId' THEN r.[ChecklistId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'checklistItemId' THEN r.[ChecklistItemId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'checklistItemId' THEN r.[ChecklistItemId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'checkDate' THEN r.[CheckDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'checkDate' THEN r.[CheckDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftId' THEN r.[ShiftId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftId' THEN r.[ShiftId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftName' THEN r.[ShiftName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftName' THEN r.[ShiftName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchName' THEN r.[ProductionBatchName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchName' THEN r.[ProductionBatchName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'workstationId' THEN r.[WorkstationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'workstationId' THEN r.[WorkstationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'resultCode' THEN r.[ResultCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'resultCode' THEN r.[ResultCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actualValue' THEN r.[ActualValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actualValue' THEN r.[ActualValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'checkedBy' THEN r.[CheckedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'checkedBy' THEN r.[CheckedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'checkedAt' THEN r.[CheckedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'checkedAt' THEN r.[CheckedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'correctiveAction' THEN r.[CorrectiveAction] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'correctiveAction' THEN r.[CorrectiveAction] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'evidenceUrl' THEN r.[EvidenceUrl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'evidenceUrl' THEN r.[EvidenceUrl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
